CREATE TABLE companies (id TEXT PRIMARY KEY, owner_user_id TEXT NOT NULL, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE company_members (company_id TEXT NOT NULL REFERENCES companies(id), user_id TEXT NOT NULL, role TEXT NOT NULL, department_id TEXT, status TEXT NOT NULL DEFAULT 'active', invited_by TEXT, joined_at TEXT NOT NULL, PRIMARY KEY (company_id, user_id));
CREATE INDEX idx_members_user ON company_members(user_id);
CREATE TABLE invitations (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), email TEXT NOT NULL, role TEXT NOT NULL, department_id TEXT, token_hash TEXT NOT NULL UNIQUE, password_enc TEXT, expires_at TEXT NOT NULL, used_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_invitations_company ON invitations(company_id);
CREATE TABLE departments (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, manager_user_id TEXT, created_at TEXT NOT NULL, UNIQUE (company_id, name));
CREATE INDEX idx_departments_company ON departments(company_id);
CREATE TABLE projects (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), department_id TEXT, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active', owner_user_id TEXT NOT NULL, start_date TEXT, end_date TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_projects_company ON projects(company_id);
CREATE TABLE tasks (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), project_id TEXT, assignee_user_id TEXT, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'todo', priority TEXT NOT NULL DEFAULT 'medium', category TEXT NOT NULL DEFAULT '', due_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_tasks_company ON tasks(company_id);
CREATE INDEX idx_tasks_project ON tasks(project_id);
CREATE INDEX idx_tasks_assignee ON tasks(assignee_user_id);
CREATE TABLE task_comments (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), task_id TEXT NOT NULL, author_user_id TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_comments_task ON task_comments(task_id, created_at);
CREATE TABLE calendar_events (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', start_at TEXT NOT NULL, end_at TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'event', visibility TEXT NOT NULL DEFAULT 'company', department_id TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_events_company ON calendar_events(company_id, start_at);
CREATE TABLE customers (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_customers_company ON customers(company_id);
CREATE TABLE documents (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), project_id TEXT, task_id TEXT, r2_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, uploaded_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_documents_company ON documents(company_id);
CREATE TABLE notifications (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), user_id TEXT NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', read_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX idx_notifications_user ON notifications(user_id, created_at);
CREATE TABLE activity_logs (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), actor_user_id TEXT NOT NULL, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE INDEX idx_logs_company ON activity_logs(company_id, created_at);
CREATE TABLE dashboard_layouts (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), user_id TEXT NOT NULL, is_company_default INTEGER NOT NULL DEFAULT 0, widgets TEXT NOT NULL DEFAULT '[]', updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX idx_layouts_personal ON dashboard_layouts(company_id, user_id) WHERE is_company_default = 0;
CREATE TABLE company_settings (company_id TEXT PRIMARY KEY REFERENCES companies(id), settings TEXT NOT NULL DEFAULT '{}');
CREATE TABLE dash_rate_limits (user_id TEXT NOT NULL, endpoint TEXT NOT NULL, window_start INTEGER NOT NULL, count INTEGER NOT NULL, PRIMARY KEY (user_id, endpoint, window_start));
CREATE TABLE dashboard_users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, mfa_secret_enc TEXT NOT NULL DEFAULT '', mfa_enabled INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE dashboard_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, user_type TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, purpose TEXT NOT NULL DEFAULT 'session', company_id TEXT, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_dashboard_sessions_user ON dashboard_sessions(user_id);
